// SPDX-License-Identifier: GPL-2.0-or-later OR MIT

#include <dt-bindings/leds/common.h>

#include "qca955x_zyxel_nbg6x16.dtsi"

/ {
	compatible = "zyxel,nbg6616", "qca,qca9557";
	model = "Zyxel NBG6616";

	aliases {
		led-boot = &led_power;
		led-failsafe = &led_power;
		led-running = &led_power;
		led-upgrade = &led_power;
	};

	leds {
		compatible = "gpio-leds";

		led_power: power {
			function = LED_FUNCTION_POWER;
			color = <LED_COLOR_ID_GREEN>;
			gpios = <&gpio 15 GPIO_ACTIVE_LOW>;
		};

		usb1 {
			label = "green:usb1";
			gpios = <&gpio 21 GPIO_ACTIVE_LOW>;
			linux,default-trigger = "usbport";
			trigger-sources = <&hub_port0>;
		};

		usb2 {
			label = "green:usb2";
			gpios = <&gpio 14 GPIO_ACTIVE_LOW>;
			linux,default-trigger = "usbport";
			trigger-sources = <&hub_port1>;
		};

		wifi5g {
			label = "green:wifi5g";
			gpios = <&gpio 17 GPIO_ACTIVE_LOW>;
			linux,default-trigger = "phy0tpt";
		};

		wps {
			function = LED_FUNCTION_WPS;
			color = <LED_COLOR_ID_GREEN>;
			gpios = <&gpio 0 GPIO_ACTIVE_LOW>;
		};
	};
};

&gpio_usb_power {
	line-name = "nbg6616:power:usb";
};

&spi {
	status = "okay";

	flash@0 {
		compatible = "jedec,spi-nor";
		reg = <0>;
		spi-max-frequency = <25000000>;

		partitions {
			compatible = "fixed-partitions";
			#address-cells = <1>;
			#size-cells = <1>;

			partition@0 {
				label = "u-boot";
				reg = <0x000000 0x030000>;
				read-only;
			};

			partition@30000 {
				label = "u-boot-env";
				reg = <0x030000 0x010000>;

				nvmem-layout {
					compatible = "u-boot,env";

					macaddr_uboot_ethaddr: ethaddr {
						#nvmem-cell-cells = <1>;
					};
				};
			};

			partition@40000 {
				label = "art";
				reg = <0x040000 0x010000>;
				read-only;

				nvmem-layout {
					compatible = "fixed-layout";
					#address-cells = <1>;
					#size-cells = <1>;

					cal_art_1000: calibration@1000 {
						reg = <0x1000 0x440>;
					};

					cal_art_5000: calibration@5000 {
						reg = <0x5000 0x844>;
					};
				};
			};

			partition@50000 {
				label = "zyxel_rfsd";
				reg = <0x050000 0x060000>;
			};

			partition@b0000 {
				label = "romd";
				reg = <0x0b0000 0x060000>;
			};

			partition@110000 {
				label = "header";
				reg = <0x110000 0x010000>;
			};

			partition@120000 {
				label = "firmware";
				reg = <0x120000 0xee0000>;
				compatible = "denx,uimage";
			};
		};
	};
};

&pcie1 {
	status = "okay";

	wifi@0,0 {
		compatible = "qcom,ath10k";
		reg = <0 0 0 0 0>;
		nvmem-cells = <&cal_art_5000>, <&macaddr_uboot_ethaddr 1>;
		nvmem-cell-names = "calibration", "mac-address";
	};
};

&wmac {
	led {
		led-sources = <19>;
		led-active-low;
	};
};

