// SPDX-License-Identifier: GPL-2.0-or-later OR MIT

#include "qca955x.dtsi"

#include <dt-bindings/gpio/gpio.h>
#include <dt-bindings/input/input.h>

/ {

	aliases {
		label-mac-device = &wmac;
	};

	keys: keys {
		compatible = "gpio-keys";

		wifi {
			label = "WiFi on/off button";
			linux,code = <KEY_RFKILL>;
			linux,input-type = <EV_SW>;
			gpios = <&gpio 1 GPIO_ACTIVE_HIGH>;
			debounce-interval = <60>;
		};

		wps {
			label = "WPS button";
			linux,code = <KEY_WPS_BUTTON>;
			gpios = <&gpio 22 GPIO_ACTIVE_LOW>;
			debounce-interval = <60>;
		};

		reset {
			label = "Reset button";
			linux,code = <KEY_RESTART>;
			gpios = <&gpio 23 GPIO_ACTIVE_LOW>;
			debounce-interval = <60>;
		};
	};
};

&gpio {
	gpio_usb_power: usb_power {
		gpio-hog;
		gpios = <16 GPIO_ACTIVE_HIGH>;
		output-high;
	};
};

&mdio0 {
	status = "okay";

	ethernet-switch@10 {
		compatible = "qca,ar8327";
		reg = <0x10>;

		qca,ar8327-initvals = <
			0x04 0x87600000 /* PORT0 PAD MODE CTRL */
			0x0c 0x00080080 /* PORT6 PAD MODE CTRL */
			0x10 0x81000080 /* POWER_ON_STRAP */
			0x50 0xffb7ffb7 /* LED_CTRL0 */
			0x54 0xffb7ffb7 /* LED_CTRL1 */
			0x58 0xffb7ffb7 /* LED_CTRL2 */
			0x5c 0x03ffff00 /* LED_CTRL3 */
			0x7c 0x0000007e /* PORT0_STATUS */
			0x94 0x0000007e /* PORT6 STATUS */
			>;
	};
};

&eth0 {
	status = "okay";

	pll-data = <0xa6000000 0x00000101 0x00001616>;

	nvmem-cells = <&macaddr_uboot_ethaddr 2>;
	nvmem-cell-names = "mac-address";

	fixed-link {
		speed = <1000>;
		full-duplex;
	};
};

&eth1 {
	status = "okay";

	pll-data = <0x03000101 0x00000101 0x00001616>;

	nvmem-cells = <&macaddr_uboot_ethaddr 3>;
	nvmem-cell-names = "mac-address";

	fixed-link {
		speed = <1000>;
		full-duplex;
	};
};

&wmac {
	status = "okay";

	nvmem-cells = <&cal_art_1000>, <&macaddr_uboot_ethaddr 0>;
	nvmem-cell-names = "calibration", "mac-address";
};

&usb_phy0 {
	status = "okay";
};

&usb_phy1 {
	status = "okay";
};

&usb0 {
	status = "okay";
};

&usb1 {
	status = "okay";
};
